<script setup lang="ts">import {fmt} from '../utils/format';defineProps<{result:any;limit?:number}>();</script><template><section class="vote-matrix"><header><strong>逐票图谱 / 前{{Math.min(limit||12,result.items.length)}}齐票试样</strong><span>同一试样的三票保持在一行；缺票试样不在三人κ内</span></header><div class="vote-scroll"><div class="vote-grid"><div class="vote-grid-head"><span>试样编号</span><span v-for="r in result.raters" :key="r">{{r}}</span><span>逐项 Pᵢ</span></div><div class="vote-row" v-for="item in result.items.slice(0,limit||12)" :key="item.id"><strong>{{item.reference}}</strong><template v-for="v in item.votes" :key="v.rater"><span v-if="v.missing" class="missing-vote">缺票</span><span v-else class="vote-cell" :class="'category-'+result.categories.indexOf(v.category)">{{v.category}}</span></template><em>{{fmt(item.agreement,3)}}</em></div></div></div></section></template>
